mapper.delete:
DELETE FROM ai_business_snapshot
WHERE snapshot_id = #{snapshotId}
  AND expires_at <= CURRENT_TIMESTAMP
  AND NOT EXISTS (
      SELECT 1
      FROM ai_business_snapshot_item item
      WHERE item.snapshot_id = #{snapshotId}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM ai_business_snapshot child
      WHERE child.source_snapshot_id = #{snapshotId}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM ai_composite_report_section section
      WHERE section.snapshot_id = #{snapshotId}
  )
  AND NOT EXISTS (
      SELECT 1
      FROM ai_project_panorama_snapshot_module panorama_module
      JOIN ai_project_panorama_snapshot panorama
        ON panorama.panorama_snapshot_id = panorama_module.panorama_snapshot_id
      WHERE panorama_module.snapshot_id = #{snapshotId}
        AND panorama.expires_at > CURRENT_TIMESTAMP
  )
  AND NOT EXISTS (
      SELECT 1
      FROM ai_business_snapshot_item artifact_item
      JOIN ai_result_artifact artifact
        ON artifact.id = artifact_item.result_artifact_id
      WHERE artifact_item.snapshot_id = #{snapshotId}
        AND artifact.expires_at > CURRENT_TIMESTAMP
  )

mapper.select:
SELECT * FROM ai_business_snapshot WHERE snapshot_id IN
#{snapshotId}
ORDER BY snapshot_id FOR UPDATE
